"""AZ-900 question bank (original questions). Lessons and animations live in az900_lessons.py."""
from builder import q

E = "az-900"
ML = "https://learn.microsoft.com/"
TR = ML + "training/modules/"
T = "frontend/src/simulations/groups/az900.test.ts"
_n = {"i": 0}


def qq(obj, diff, typ, stem, opts, correct, expl, doc, mode=None, code=None):
    """Compact question helper: opts = [(text, explanation)], correct = letters."""
    _n["i"] += 1
    letters = "abcdefgh"
    m = mode or ("multiple" if len(correct) > 1 else "single")
    args = [f"az900-q-{obj.split('-')[1]}-{_n['i']}", E, obj, diff, typ, m, stem]
    if code:
        args.append(code)
    q(*args, [(letters[i], o[0], o[1]) for i, o in enumerate(opts)], list(correct), expl, [doc])


def cfg(portal, cli, ps, prereq=("An Azure subscription (a free account works)",), perms=("Reader to explore; Contributor to create resources",), limits=("Concept-level: no limits to configure",)):
    return dict(prerequisites=list(prereq), permissions=list(perms), limits=list(limits), portal=portal, cli=cli, powershell=ps)


def chooser_lab(sim_id, scenario, what):
    return dict(type="A", objective=f"Practise choosing the right {what}.", duration=10,
                steps=[f"Open the '{scenario}' tab.", "Pick a requirement and an answer, run it, and read the explanation.", "Repeat until every requirement gives GOOD FIT."],
                expected=["Each choice is explained"], validation=[(f"{sim_id}-correct", f"Chose a correct {what}"), (f"{sim_id}-wrong", "Learned from a wrong choice")], failures=["Picking by name rather than by requirement"])



